def seed_procurement_catalog(apps, schema_editor):
    """Register the public procurement modules without granting any tenant access."""
    db = schema_editor.connection.alias
    Catalog = apps.get_model('platform_core', 'ERPCatalog')
    Module = apps.get_model('platform_core', 'ERPProductModule')
    Resource = apps.get_model('platform_core', 'ERPProductResource')
    product = Catalog.objects.using(db).get(code='gestao-publica')
    definitions = (
        ('compras_publicas', 'Compras Públicas'),
        ('licitacoes_publicas', 'Licitações Públicas'),
        ('registro_precos', 'Registro de Preços'),
        ('contratos_publicos', 'Contratos Públicos'),
    )
    modules = {}
    for order, (code, name) in enumerate(definitions, start=30):
        module, _ = Module.objects.using(db).get_or_create(
            erp_id=product.pk, code=code,
            defaults={'name': name, 'active': True, 'sort_order': order},
        )
        modules[code] = module
    resources = (
        ('compras_publicas', 'solicitacoes', 'Solicitações de compra'),
        ('compras_publicas', 'pesquisa_precos', 'Pesquisa e mapa comparativo de preços'),
        ('compras_publicas', 'modalidades', 'Modalidades parametrizáveis'),
        ('licitacoes_publicas', 'processos', 'Processos de contratação'),
        ('licitacoes_publicas', 'editais', 'Editais, participantes e propostas'),
        ('licitacoes_publicas', 'julgamento', 'Julgamento e histórico de etapas'),
        ('registro_precos', 'atas', 'Atas, itens, saldo e utilizações'),
        ('contratos_publicos', 'contratos', 'Contratos, aditivos e execução'),
        ('contratos_publicos', 'documentos', 'Documentos privados de contratação'),
    )
    for order, (module_code, code, name) in enumerate(resources, start=30):
        Resource.objects.using(db).get_or_create(
            module_id=modules[module_code].pk, code=code,
            defaults={'name': name, 'active': True, 'sort_order': order},
        )


